<body><main class="shell"><header><div class="brand"><div class="brand-icon"><i></i><i></i><i></i><i></i></div><div><h1>BLOCKBOUND</h1><p>STACK SMART. JUMP HIGH.</p></div></div><div class="top-note"><span>↗</span> a little Tetris, a lot of air time</div></header>
<div class="layout"><section class="game-card"><div class="stage-head"><div class="stage-label">THE PLAYGROUND &nbsp;·&nbsp; 10 × 18</div><div class="live" id="status">READY</div></div><div class="canvas-wrap"><canvas id="game" width="500" height="650" aria-label="Blockbound game area"></canvas><div class="toast" id="toast">LINE CLEARED · PLATFORM FORMED</div><div class="overlay" id="overlay"><div class="modal"><div class="eyebrow" id="modal-eyebrow">A NEW KIND OF STACK</div><h2 id="modal-title">Clear a line.<br>Make a way up.</h2><p id="modal-copy">Stack falling blocks to clear rows. Every cleared line leaves a temporary platform—jump onto it and climb your way to a high score.</p><button class="primary" id="start">LET'S PLAY&nbsp; ↗</button></div></div></div><div class="touch-controls" aria-label="Touch controls"><button data-action="left" aria-label="Move left">←</button><button data-action="piece-left" aria-label="Slide block left">↤</button><button data-action="jump" aria-label="Jump">↑</button><button data-action="right" aria-label="Move right">→</button><button data-action="piece-right" aria-label="Slide block right">↦</button><button data-action="rotate" aria-label="Rotate piece">⟳</button><button data-action="drop" aria-label="Drop piece">↓</button></div></section>
<aside class="side"><section class="side-card"><div class="side-title">Run stats</div><div class="stats"><div class="stat"><span>SCORE</span><strong class="accent" id="score">00000</strong></div><div class="stat"><span>BEST</span><strong id="best">00000</strong></div><div class="stat"><span>LINES</span><strong id="lines">00</strong></div><div class="stat"><span>LEVEL</span><strong id="level">01</strong></div></div></section><section class="side-card"><div class="side-title">Up next</div><canvas id="next" width="200" height="94"></canvas><p class="objective"><b>Clear rows</b> to conjure short-lived platforms. <b>Jump</b> onto the stacks and stay airborne as long as you can.</p></section><section class="side-card controls-card"><div class="side-title">How to play</div><div class="controls"><div class="control-row"><span>Move / jump</span><span class="key">A D / SPACE</span></div><div class="control-row"><span>Slide block</span><span class="key">J / L</span></div><div class="control-row"><span>Rotate piece</span><span class="key">W / ↑</span></div><div class="control-row"><span>Soft / hard drop</span><span class="key">↓ / SHIFT</span></div><div class="pause-row"><p>Esc to pause</p><button class="icon-btn" id="pause" aria-label="Pause game">Ⅱ</button></div></div></section></aside></div><footer>ONE BUTTON TO JUMP · ONE LINE TO CHANGE EVERYTHING</footer></main>
<script>
(()=>{
const cv=document.querySelector('#game'),ctx=cv.getContext('2d'),ncv=document.querySelector('#next'),nctx=ncv.getContext('2d');
const W=500,H=650,C=32,COLS=10,ROWS=18,BX=90,BY=37,BW=C*COLS,BH=C*ROWS;
const palette={I:'#63ded4',O:'#f4d45d',T:'#b88aff',S:'#9cdd70',Z:'#ff7f9b',J:'#76aaff',L:'#ffad68'};
const shapes={I:[[1,1,1,1]],O:[[1,1],[1,1]],T:[[0,1,0],[1,1,1]],S:[[0,1,1],[1,1,0]],Z:[[1,1,0],[0,1,1]],J:[[1,0,0],[1,1,1]],L:[[0,0,1],[1,1,1]]};
let board=Array.from({length:ROWS},()=>Array(COLS).fill(null)),piece,next,platforms=[],player={x:BX+BW/2-10,y:BY+BH-25,vx:0,vy:0,onGround:true,face:1},score=0,lines=0,level=1,best,fallTimer=0,toastTimer=0,last=0,active=false,paused=false,over=false,keys={},lastMove=0;
const $=s=>document.querySelector(s),overlay=$('#overlay');
best=Number(localStorage.getItem('blockbound-best')||0);$('#best').textContent=String(best).padStart(5,'0');
